parameters.jsCode:
const raw = $input.first().json.output;
let text = (typeof raw === 'string' ? raw : '').trim();

// Slack mrkdwn uses single asterisks. The model emits ** despite the prompt
// forbidding it, and Slack shows those as literal characters. Fixed here rather
// than asked for again.
text = text.replace(/\*{2,}/g, '*');

const fallback = "Sorry — I lost the thread on that one. Could you say it again?";
return [{ json: { output: text.length ? text : fallback } }];

// Collapses Slack history back to ONE item - a multi-item node in the agent's
// main chain breaks paired-item resolution (HANDOFF 7.2). Everything downstream
// reads this node with .first().
//
// The gate: `confirmed` is true only when the last thing Jessie said in this DM
// was a summary ending in the marker line, AND the requester has said something
// since. Send Reply runs after the agent, so a summary written in the current
// turn is not in Slack yet - a same-turn booking cannot pass this. The model
// supplies no part of it.
const MARKERS = { book: 'confirm to book.', cancel: 'confirm to cancel.', move: 'confirm to move.' };
// A reply only approves something. A fresh instruction is not an approval, which
// is how a booking once went through with no summary: the previous bot message
// still ended with the marker, and the next request counted as the yes.
const isNewRequest = t => (/\b(book|rebook|reschedule|cancel|move)\b/i.test(t) && t.trim().length > 30)
                          || /^reset$/i.test(t.trim());   // reset clears memory, it approves nothing
const BOT_USER = 'U0BNQL8KFKR';   // Jessie's own Slack user, seen on her replies
// Anything sent through the Claude Slack connector arrives with a trailing
// "*Sent using* <@U0AVDBNH1K4>". Every whole-message match has to see past it,
// or the message is a different string than the one that was typed.
const clean = s => String(s || '').replace(/\*sent using\*[\s\S]*$/i, '').trim();

const trigger = $('Slack Trigger').first().json || {};
const booker = $('Get Booker').first().json || {};
let msgs = [];
try { msgs = $('Get Recent Messages').all().map(i => (i && i.json) ? i.json : {}); } catch (e) { msgs = []; }

const isBot = m => Boolean(m.bot_id) || m.subtype === 'bot_message' || m.user === BOT_USER;

// Memory epoch. Only a typed "reset" ends the conversation for memory purposes.
// A finished booking used to end it too, so the next request could not inherit
// its client or session type - but that also meant "cancel that" straight after
// a booking had nothing to refer to. Inheriting is now caught by the summary,
// which is read before anything is created; forgetting was not caught by
// anything. Tara's call, 2026-08-30.
//
// Held in workflow static data and only ever moves forward. Deriving it from
// the history window alone was wrong: once the marker aged out of the window
// the epoch fell back to empty, the key changed and the thread lost context.
// Read off this message rather than waiting for it to appear in the history
// window. The epoch used to advance only because the loop below found "reset"
// in the last 12 messages, which depends on Slack having already returned the
// message that triggered this run.
const isReset = /^reset$/i.test(clean(trigger.text));

const store = $getWorkflowStaticData('global');
const slackUser = String($('Slack Trigger').first().json.user || '');
const storeKey = 'epoch_' + slackUser;
let epoch = String(store[storeKey] || '');
for (const m of msgs) {
  const t = clean(m.text);
  const ts = String(m.ts || '');
  const marks = !isBot(m) && /^reset$/i.test(t);
  if (marks && ts && parseFloat(ts) > parseFloat(epoch || '0')) { epoch = ts; break; }
  if (marks) break;
}
if (isReset && trigger.ts && parseFloat(trigger.ts) > parseFloat(epoch || '0')) {
  epoch = String(trigger.ts);
}
store[storeKey] = epoch;

// Slack returns newest first. Walk back to the first bot message, counting any
// requester messages passed on the way - those are the reply that came after it.
let repliedSince = 0, lastBotText = '', found = false, sawNewRequest = false;
for (const m of msgs) {
  if (isBot(m)) { lastBotText = String(m.text || ''); found = true; break; }
  const t = String(m.text || '');
  if (t.trim()) { repliedSince++; if (isNewRequest(t)) sawNewRequest = true; }
}


// --- what day it is, once, for everything below --------------------------
// YEAR_SHIFT matches the prompt's plus({ years: 1 }) QA convention. Both must
// go to 0 together before launch, or the model and this code disagree about
// what day it is - and this node decides what "next Thursday" means.
const YEAR_SHIFT = 1;
const DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const MONTHNAMES = ['January','February','March','April','May','June','July','August',
                    'September','October','November','December'];
const manila = new Date(Date.now() + 8 * 3600 * 1000);
const today = new Date(Date.UTC(manila.getUTCFullYear() + YEAR_SHIFT, manila.getUTCMonth(),
                                manila.getUTCDate()));
const addDays = (d, n) => new Date(d.getTime() + n * 86400000);
const show = d => DAYS[d.getUTCDay()] + ', ' + d.getUTCDate() + ' ' + MONTHNAMES[d.getUTCMonth()]
                + ' ' + d.getUTCFullYear() + ' (' + d.toISOString().slice(0, 10) + ')';

// --- a date that has already passed --------------------------------------
// Read out of the message here rather than left to the model to notice. Only
// dates carrying an explicit year are checked: without one, a date resolves
// against "today" in the prompt and cannot be in the past.
const MONTHS = { jan:0, feb:1, mar:2, apr:3, may:4, jun:5, jul:6, aug:7, sep:8, oct:9, nov:10, dec:11 };
function explicitDate(text) {
  const t = String(text || '');
  let m;
  // 2026-07-01
  m = t.match(/\b(\d{4})-(\d{2})-(\d{2})\b/);
  if (m) return { y:+m[1], mo:+m[2]-1, d:+m[3], shown:m[0] };
  // 1 July 2026  /  1 Jul 2026
  m = t.match(/\b(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]{3,9})\.?,?\s+(\d{4})\b/);
  if (m && MONTHS[m[2].slice(0,3).toLowerCase()] !== undefined)
    return { y:+m[3], mo:MONTHS[m[2].slice(0,3).toLowerCase()], d:+m[1], shown:m[0] };
  // July 1 2026  /  July 1st, 2026
  m = t.match(/\b([A-Za-z]{3,9})\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})\b/);
  if (m && MONTHS[m[1].slice(0,3).toLowerCase()] !== undefined)
    return { y:+m[3], mo:MONTHS[m[1].slice(0,3).toLowerCase()], d:+m[2], shown:m[0] };
  return null;
}
let pastDate = '', pastDateNotice = '';
const pastHit = explicitDate(String(trigger.text || ''));
if (pastHit) {
  // Compared against the date the model is told it is, not the real one. With
  // YEAR_SHIFT on those are a year apart, so a 2027 date that had already passed
  // from the requester's point of view was sailing through unflagged.
  const asked = Date.UTC(pastHit.y, pastHit.mo, pastHit.d);
  if (asked < today.getTime()) {
    pastDate = pastHit.shown;
    pastDateNotice = 'THE DATE THEY GAVE HAS ALREADY PASSED: ' + pastHit.shown + '. Before anything else, '
      + 'tell them that date is in the past and ask for the correct one. Do not ask for the session type, '
      + 'the client, the project or the engineer, and do not attempt to book it.';
  }
}

// What counts as a yes. Until now `confirmed` only required that the requester
// had said something that was not a fresh instruction - so "no" passed the gate.
// Harmless while the model still had to decide to act; not harmless once
// cancelNotice started telling it the cancellation was approved. Tara's call,
// 2026-08-30: the requester is offered y/n and the gate matches that literally,
// with nothing interpreted.
const YES = /^(y|yes|yeah|yep|yup|ok|okay|k|sure|sige|oo|opo|confirm|confirmed|correct|right|go|go ahead|do it|proceed|book it|cancel it|yes please|please do|\u{1F44D}|\u{2705})$/iu;
const NO  = /^(n|no|nope|nah|hindi|wait|stop|hold on|not yet|never ?mind|wrong|change it)$/i;
const said = clean(trigger.text).replace(/[.!,]+$/, '').trim();
const saidYes = YES.test(said);
const saidNo  = NO.test(said);

// (y/n) is part of what she now writes; the marker match ignores it, so a reply
// still lands whether or not the model remembered to add it.
// --- relative dates, resolved here rather than by the model ---------------
// "next Thursday" resolved to 2027-09-09 in one run and 2027-09-02 seven
// minutes later, from the same prompt date. She also printed the wrong weekday
// beside a right date - "September 9, 2027 (Wed)" for a Thursday - which is
// worse, because the weekday is what a booker scans before typing y.
//
// Tara's rule, 2026-08-30: "next Thursday" is the Thursday of NEXT week,
// because "this Thursday" is the one in the current week. Weeks start Monday.
const weekMonday = addDays(today, -((today.getUTCDay() + 6) % 7));
const dayIndex = n => DAYS.map(d => d.toLowerCase()).indexOf(String(n).toLowerCase());
const dateLines = [];
let primaryDate = null;
const seenPhrase = {};
const note = (phrase, date, extra) => {
  const k = phrase.toLowerCase();
  if (seenPhrase[k]) return;
  seenPhrase[k] = 1;
  if (!primaryDate) primaryDate = date;
  dateLines.push('- "' + phrase + '" = ' + show(date) + (extra ? '  ' + extra : ''));
};
const msgText = clean(trigger.text);
const DAYRE = '(sunday|monday|tuesday|wednesday|thursday|friday|saturday)';
let dm;

const reNext = new RegExp('\\bnext\\s+' + DAYRE + '\\b', 'gi');
while ((dm = reNext.exec(msgText)) !== null)
  note(dm[0], addDays(weekMonday, 7 + ((dayIndex(dm[1]) + 6) % 7)));

const reThis = new RegExp('\\bthis\\s+' + DAYRE + '\\b', 'gi');
while ((dm = reThis.exec(msgText)) !== null)
  note(dm[0], addDays(weekMonday, (dayIndex(dm[1]) + 6) % 7));

// A bare weekday is the next one coming up, which is not the same as
// "next <day>" - worth saying out loud rather than assuming they agree.
const reBare = new RegExp('(?<!\\b(?:next|this|last)\\s)\\b' + DAYRE + '\\b', 'gi');
while ((dm = reBare.exec(msgText)) !== null) {
  let target = addDays(weekMonday, (dayIndex(dm[1]) + 6) % 7);
  if (target.getTime() < today.getTime()) target = addDays(target, 7);
  note(dm[0], target, '(the next one - if they meant the week after, that is "next ' + dm[1] + '")');
}
if (/\btomorrow\b/i.test(msgText)) note('tomorrow', addDays(today, 1));
if (/\b(today|tonight)\b/i.test(msgText)) note('today', today);
if (pastHit) note(pastHit.shown, new Date(Date.UTC(pastHit.y, pastHit.mo, pastHit.d)));

// A follow-up that says "that slot" carries no date phrase, so nothing above
// fires and the model works the date out again from memory. On 2026-08-30 "what
// are all my options for that slot?" was answered from 2027-09-16 availability
// in a conversation about the 9th. So the resolved date is remembered and stated
// back on the turns that do not name one. Any date in the message wins over it,
// and a reset clears it.
// Bounded to this conversation and this day. Without that it would still be
// answering about last Thursday a week later - the epoch changes on reset and
// the day stamp changes at midnight, and either one retires it.
const dateKey = 'lastdate_' + slackUser;
const todayStamp = today.toISOString().slice(0, 10);
if (isReset) { delete store[dateKey]; }
else if (primaryDate) {
  store[dateKey] = { date: primaryDate.toISOString().slice(0, 10), epoch: epoch, day: todayStamp };
}
const carriedRec = store[dateKey];
const carriedOk = Boolean(carriedRec && carriedRec.date
                          && carriedRec.epoch === epoch && carriedRec.day === todayStamp);

let dateNotice = '';
if (dateLines.length) {
  dateNotice = 'DATES IN THIS MESSAGE, ALREADY RESOLVED. Use these exactly, including the day of the week, '
             + 'and do not work them out again:\n' + dateLines.join('\n');
} else if (carriedOk) {
  const carried = new Date(carriedRec.date + 'T00:00:00Z');
  dateNotice = 'THE DATE UNDER DISCUSSION IS ' + show(carried) + '. Anything in this message about "that '
             + 'slot", "then", or the same booking means that date. Use it as given and do not work it out '
             + 'again. If they name a different date, that one wins.';
}

const tail = lastBotText.trim().toLowerCase().replace(/\(y\/n\)$/, '').trim();
const endsWith = m => found && tail.endsWith(m);
const approvalOnly = repliedSince > 0 && !sawNewRequest;

const confirmed       = endsWith(MARKERS.book)   && saidYes;
const confirmedCancel = endsWith(MARKERS.cancel) && saidYes;
// A move is one action with one approval - Move Booking creates the replacement
// and removes the original itself. Before it existed, a reschedule needed two
// separate yeses and deleted the booking after the first one.
const confirmedMove   = endsWith(MARKERS.move)   && saidYes;

// A no is worth stating too, or the model reads it as a request it did not
// understand and shows the same summary again.
// The clearing is done in code, one node before the model sees anything - but
// nothing told the model that, so from where it sits "reset" is just a word
// someone typed. It has answered "I can't reset or clear message metadata"
// on a turn where the epoch had already moved, which is a lie about work that
// had already happened. Five runs produced five different answers.
const resetNotice = isReset
  ? 'THE CONVERSATION HAS JUST BEEN CLEARED. It already happened, before this message reached you - '
    + 'you no longer have anything from before it. Reply with exactly: All cleared. What do you need? '
    + 'Say nothing else, do not explain what reset does, and never say you cannot clear it.'
  : '';

const declineNotice = (saidNo && (endsWith(MARKERS.book) || endsWith(MARKERS.cancel) || endsWith(MARKERS.move)))
  ? 'THEY SAID NO to what you just showed them. Nothing was created and nothing was '
    + 'cancelled. Ask what they want changed. Do not show that same summary again unchanged.'
  : '';

// Book Session enforces `confirmed` itself, so the model is not told about it.
// Nothing enforces the cancel: the prompt asks the model to notice the approval
// and call Cancel Booking, and on 2026-08-30 it instead re-ran the search and
// re-presented the same summary three times running. So the approval is stated
// as a fact the same way pastDateNotice is, rather than left to be inferred.
const moveNotice = confirmedMove
  ? 'THE MOVE IS ALREADY APPROVED. Your next action is one call to Move Booking, with the booking title '
    + 'and its current date exactly as you showed them, plus the new start and end. Do not cancel anything '
    + 'and do not book anything separately - Move Booking does both. Do not show that summary again.'
  : '';

const cancelNotice = confirmedCancel
  ? 'THE CANCELLATION IS ALREADY APPROVED. They have just said yes to the summary you showed them. '
    + 'Your next action is one call to Cancel Booking, with the booking title and date exactly as you '
    + 'showed them. Do not search first - Cancel Booking finds the booking itself, and searching instead '
    + 'of cancelling is the one failure this notice exists to stop. Do not present that summary again '
    + 'and do not ask again. When it comes back, say what it tells you and nothing more.'
  : '';

return [{ json: Object.assign({}, booker, {
  pastDate: pastDate,
  pastDateNotice: pastDateNotice,
  dateNotice: dateNotice,
  cancelNotice: cancelNotice,
  moveNotice: moveNotice,
  declineNotice: declineNotice,
  resetNotice: resetNotice,
  epoch: epoch,
  confirmed: confirmed,
  confirmedCancel: confirmedCancel,
  confirmedMove: confirmedMove,
  gate: { presentedBook: endsWith(MARKERS.book), presentedCancel: endsWith(MARKERS.cancel), presentedMove: endsWith(MARKERS.move),
          repliedSince: repliedSince, sawNewRequest: sawNewRequest, said: said, saidYes: saidYes, saidNo: saidNo, sawBotMessage: found,
          historyCount: msgs.length, lastBotText: lastBotText.slice(-120) }
}) }];

// Builds the room-ranking reference the system prompt interpolates. The lists
// live in Airtable as record ids the model cannot read, and it will not call a
// tool to resolve them - so they are resolved here and handed to it as text.
const nameOf = {};
try {
  for (const it of $('All Rooms').all()) {
    const r = (it && it.json) || {};
    if (r.id) nameOf[r.id] = String((r.fields || {})['Room Name'] || '').trim();
  }
} catch (e) {}

const lines = [];
try {
  for (const it of $('All Session Types').all()) {
    const f = ((it && it.json) || {}).fields || {};
    const type = String(f['Type'] || '').trim();
    if (!type) continue;
    const names = ids => [].concat(ids || []).map(i => nameOf[i]).filter(Boolean);
    const pri = names(f['Priority']), last = names(f['Last Resort']);
    if (!pri.length && !last.length) continue;
    lines.push('- ' + type + ' — priority: ' + (pri.join(', ') || 'none on file')
             + (last.length ? ' · last resort: ' + last.join(', ') : ''));
  }
} catch (e) {}

lines.sort();

// The session types, read live, so the list she offers cannot go stale when Tel
// adds one - which had already happened: Localization Atmos Mixing existed in
// Airtable and appeared nowhere in the prompt.
const typeNames = [];
try {
  for (const it of $('All Session Types').all()) {
    const t = String((((it && it.json) || {}).fields || {})['Type'] || '').trim();
    if (t && typeNames.indexOf(t) === -1) typeNames.push(t);
  }
} catch (e) {}
typeNames.sort();

// A department-flavoured e.g. for the session-type question. Not a filter -
// bookers routinely book outside their own department, and eight of the eleven
// departments map to no session type at all. The full list stays available.
const DEPT_ROLES = {
  'audio post':   ['post engineer'],
  'localization': ['loc engineer'],
  'music':        ['music engineer', 'music arranger']
};
const bookerFields = (function(){ try { return ($('Get Booker').first().json || {}).fields || {}; }
                                  catch (e) { return {}; } })();
const myRoles = [];
for (const d of [].concat(bookerFields['Department'] || [])) {
  for (const r of (DEPT_ROLES[String(d).trim().toLowerCase()] || [])) myRoles.push(r);
}
const suggested = [];
if (myRoles.length) {
  try {
    for (const it of $('All Session Types').all()) {
      const f = ((it && it.json) || {}).fields || {};
      const t = String(f['Type'] || '').trim();
      if (!t) continue;
      const roles = [].concat(f['Engineer Role Required'] || []).map(r => String(r).trim().toLowerCase());
      if (roles.some(r => myRoles.indexOf(r) !== -1) && suggested.indexOf(t) === -1) suggested.push(t);
    }
  } catch (e) {}
}
suggested.sort();
const sessionTypeHint = suggested.length ? suggested.join(', ') : '';
const sessionTypes = typeNames.length
  ? typeNames.join(' · ')
  : '(session type list unavailable this run - ask Session Types before offering any)';
const text = lines.length
  ? lines.join('\n')
  : '(room ranking unavailable this run - ask Rooms and Studios before naming any room)';
// Reference data for the sub-workflows. Both used to re-read these two tables
// on every call, so on a booking turn the same tables were fetched three times.
// Passed down instead - resolved once, here.
const refRooms = [];
try {
  for (const it of $('All Rooms').all()) {
    const r = (it && it.json) || {}; const f = r.fields || {};
    if (r.id && f['Room Name']) refRooms.push({ id: r.id, name: String(f['Room Name']).trim() });
  }
} catch (e) {}
const refTypes = [];
try {
  for (const it of $('All Session Types').all()) {
    const r = (it && it.json) || {}; const f = r.fields || {};
    const t = String(f['Type'] || '').trim();
    if (!t) continue;
    refTypes.push({ type: t, min: f['Min Duration (mins)'] || null, max: f['Max Duration (mins)'] || null,
                    priority: [].concat(f['Priority'] || []), last: [].concat(f['Last Resort'] || []) });
  }
} catch (e) {}
// --- "book Studio F for Howard" ------------------------------------------
// A name after "for" is not the client, and on 2026-08-30 she put one in the
// client field without asking: "Book Studio F for Howard" produced the title
// ORION / Howard / TL, with no lookup and no question. Howard is staff.
//
// Detected here rather than in Gate Context because only this node can see the
// session-type list, and "for Post Mixing" looks identical to "for Howard".
// Room names are excluded for the same reason. It does not try to work out what
// the name is - it only stops the client field being filled from a guess.
let forNameNotice = '';
try {
  const msg = String(($('Slack Trigger').first().json || {}).text || '')
    .replace(/\*sent using\*[\s\S]*$/i, '');
  const saidClient = /\bclients?\b/i.test(msg);
  const known = []
    .concat(typeNames.map(t => t.toLowerCase()))
    .concat(refRooms.map(r => r.name.toLowerCase()));
  const hits = [];
  const re = /\bfor\s+([A-Z][\w.'-]*(?:\s+[A-Z][\w.'-]*){0,3})/g;
  let m;
  while ((m = re.exec(msg)) !== null) {
    const phrase = m[1].trim();
    const low = phrase.toLowerCase();
    if (known.some(k => k && (low === k || low.indexOf(k) === 0 || k.indexOf(low) === 0))) continue;
    hits.push(phrase);
  }
  if (!saidClient && hits.length) {
    forNameNotice = 'THEY WROTE "for ' + hits[0] + '" AND HAVE NOT SAID WHO THE CLIENT IS. A name after '
      + '"for" is not the client - it is as likely to be the person you are booking on behalf of, or the '
      + 'project. Do not put it in the client field or the title on that basis. Ask who the client is, and '
      + 'ask what ' + hits[0] + ' is if it is still unclear, before you present any summary. Internal rooms '
      + '- M Booth, Lobby and Conference Room - have no client, so ignore this if the booking is one of those.';
  }
} catch (e) {}

// The prompt used to carry a written-out room list. Rooms come from Airtable
// already, so it is built here instead - one less list that can go stale, and
// no extra call, since All Rooms was read this turn anyway.
const roomNames = refRooms.length
  ? refRooms.map(r => r.name).join(' · ')
  : '(room list unavailable this run - ask Rooms and Studios)';

const referenceData = (refRooms.length && refTypes.length)
  ? JSON.stringify({ rooms: refRooms, types: refTypes }) : '';

return [{ json: Object.assign({}, $('Gate Context').first().json, { referenceData: referenceData, roomTable: text, sessionTypes: sessionTypes, sessionTypeHint: sessionTypeHint, forNameNotice: forNameNotice, roomNames: roomNames }) }];
